message.content:
{
  "cards": [
    {
      "pages": [9, 10],
      "encounter_types": ["unknown", "restricted_visibility"],
      "roles": ["not_applicable"],
      "encounter_phases": ["monitoring", "risk_developing"],
      "warning_signs": ["Dedicated lookout assigned duties away from the bridge", "OOW acting as sole lookout in darkness or restricted visibility"],
      "causal_mechanisms": ["poor_monitoring"],
      "investigator_finding": "Cepheus J's dedicated lookout was sent away to clean, leaving the OOW as sole lookout in darkness, contrary to the cited watchkeeping requirements.",
      "transferable_lesson": "Retain dedicated lookout coverage in darkness or restricted visibility rather than assigning the lookout conflicting duties.",
      "non_transfer_conditions": ["The specific sole-lookout finding does not establish that sole watchkeeping is prohibited in every daylight situation."],
      "supporting_quotes": [
        {
          "page": 9,
          "quote": "The OOW had sent the dedicated lookout away from the bridge, to carry out cleaning tasks elsewhere in the ship."
        },
        {
          "page": 10,
          "quote": "it is not safe for the officer of the navigational watch to act as sole lookout during periods of darkness or restricted visibility."
        }
      ]
    },
    {
      "pages": [9],
      "encounter_types": ["unknown"],
      "roles": ["uncertain"],
      "encounter_phases": ["monitoring", "risk_developing"],
      "warning_signs": ["OOW occupied with paperwork", "Entertainment or news audio competing with VHF monitoring"],
      "causal_mechanisms": ["distraction", "poor_monitoring"],
      "investigator_finding": "Paperwork and radio news distracted the OOW from visual and radar lookout and effective VHF monitoring.",
      "transferable_lesson": "Keep administrative work and non-operational audio from displacing visual, radar and auditory watchkeeping; functioning equipment alone does not ensure detection.",
      "non_transfer_conditions": ["This finding does not establish that every administrative task or audio source necessarily impairs a properly maintained watch."],
      "supporting_quotes": [
        {
          "page": 9,
          "quote": "Cepheus J’s OOW was involved in tasks which distracted him from his primary duty of lookout."
        },
        {
          "page": 9,
          "quote": "This meant that he was not paying attention to the radar or to keeping a visual lookout."
        },
        {
          "page": 9,
          "quote": "Because he was listening to the news on the radio, he was unable to monitor the VHF radio effectively"
        }
      ]
    },
    {
      "pages": [11, 13],
      "encounter_types": ["unknown", "restricted_visibility"],
      "roles": ["uncertain"],
      "encounter_phases": ["monitoring", "risk_developing"],
      "warning_signs": ["Radar operating without acquired targets", "No systematic observations of detected contacts", "Available ARPA acquisition and alerting facilities unused"],
      "causal_mechanisms": ["poor_monitoring", "inadequate_cpa_assessment"],
      "investigator_finding": "Cepheus J's radar was operating, but no ARPA targets were acquired and no other systematic observation was undertaken; acquisition could have alerted the OOW to the collision risk.",
      "transferable_lesson": "Systematically observe detected contacts and use available target acquisition and collision-risk information rather than treating an operating radar as a completed risk assessment.",
      "non_transfer_conditions": ["ARPA-specific acquisition and alerting implications do not apply to equipment without those facilities; systematic observation remains relevant."],
      "supporting_quotes": [
        {
          "page": 11,
          "quote": "VDR recorded the fact that the radar was operating, but that no targets had been acquired with the ARPA."
        },
        {
          "page": 11,
          "quote": "It also showed that no other systematic observation of detected objects was being carried out."
        },
        {
          "page": 13,
          "quote": "Had either manual or automatic acquisition of targets been used, the OOW would have been alerted to the possible collision with Ileksa"
        }
      ]
    },
    {
      "pages": [13, 14],
      "encounter_types": ["unknown"],
      "roles": ["uncertain"],
      "encounter_phases": ["monitoring", "risk_developing"],
      "warning_signs": ["Radar contact close to or beneath the heading marker", "Relative trails masked by display symbology", "AIS symbol visible beside a difficult-to-see radar return"],
      "causal_mechanisms": ["poor_monitoring", "other"],
      "investigator_finding": "The heading marker obscured Ileksa's radar return and relative trail, while an offset AIS symbol provided an additional indication of the vessel.",
      "transferable_lesson": "Account for display masking when checking for contacts near the heading marker, and use available complementary indications to investigate a potentially obscured target.",
      "non_transfer_conditions": ["The report's confident association of the offset AIS symbol with the radar return depended on there being no other nearby targets; it does not establish reliable association in cluttered multi-contact situations."],
      "supporting_quotes": [
        {
          "page": 14,
          "quote": "Since the relative approach of Ileksa was down the heading marker, the relative trails would also have painted there, so would have been masked to the observer."
        },
        {
          "page": 13,
          "quote": "The AIS target positioned to one side of the heading marker, would have highlighted the presence of a target near that position."
        },
        {
          "page": 13,
          "quote": "there could be no doubt that the two were the same vessel, since there were no other targets in the vicinity."
        }
      ]
    },
    {
      "pages": [13],
      "encounter_types": ["unknown"],
      "roles": ["uncertain"],
      "encounter_phases": ["monitoring", "risk_developing"],
      "warning_signs": ["Manually marked plotting-aid positions updated infrequently", "Target information potentially stale"],
      "causal_mechanisms": ["poor_monitoring", "inadequate_cpa_assessment"],
      "investigator_finding": "Ileksa's elementary plotting aid required frequent position marking for reliable, current information; although that facility was unused, a paper plot supported collision-risk assessment.",
      "transferable_lesson": "Match the updating discipline to the plotting method, and judge risk-assessment adequacy by systematic, current observations rather than by whether every radar facility is selected.",
      "non_transfer_conditions": ["Manual marking requirements do not transfer directly to automatic tracking systems with different update mechanisms."],
      "supporting_quotes": [
        {
          "page": 13,
          "quote": "it required continuous monitoring to ensure that the target was marked sufficiently frequently to give reliable and up to date information."
        },
        {
          "page": 13,
          "quote": "a paper plot was being maintained by the third officer, from ranges and bearings read off from the radar by the master."
        },
        {
          "page": 13,
          "quote": "Not all the facilities of the radar were being used, but Ileksa was aware of the presence of Cepheus J and had assessed the risk of collision."
        }
      ]
    },
    {
      "pages": [11, 15],
      "encounter_types": ["overtaking"],
      "roles": ["stand_on"],
      "encounter_phases": ["risk_developing", "action_required"],
      "warning_signs": ["Approaching vessel apparently taking no avoiding action", "Expectation that an overtaking vessel will act late", "Collision risk already determined"],
      "causal_mechanisms": ["delayed_action"],
      "investigator_finding": "Ileksa's OOW was accustomed to late avoiding action by overtaking vessels and was not unduly concerned by Cepheus J's approach; the investigation concluded Ileksa should have acted earlier once non-action became clear.",
      "transferable_lesson": "Do not let familiarity with late passing manoeuvres override evidence that the approaching vessel is failing to act; reassess the need for own action as that evidence develops.",
      "non_transfer_conditions": ["This does not imply immediate own-ship manoeuvring whenever another vessel has not yet acted, or remove the need to assess the applicable encounter circumstances."],
      "supporting_quotes": [
        {
          "page": 11,
          "quote": "the OOW was used to vessels taking late avoiding action."
        },
        {
          "page": 11,
          "quote": "He was, therefore, not unduly concerned that Cepheus J was approaching and, apparently, taking no action."
        },
        {
          "page": 15,
          "quote": "Once it became clear that Cepheus J was taking no action, Ileksa should have taken action earlier, given the prevailing weather conditions."
        }
      ]
    },
    {
      "pages": [11, 12],
      "encounter_types": ["unknown"],
      "roles": ["uncertain"],
      "encounter_phases": ["risk_developing", "action_required"],
      "warning_signs": ["Limited manoeuvring capability", "Strong headwind and reduced speed through the water", "Little heading response after helm application"],
      "causal_mechanisms": ["delayed_action", "ineffective_action"],
      "investigator_finding": "Ileksa's limited manoeuvrability and prevailing wind delayed the effect of avoiding action; those limitations should have prompted earlier action.",
      "transferable_lesson": "Include actual weather-dependent manoeuvring response in the time allowed for avoidance, rather than relying on calm-water response or assuming a helm order will have an immediate effect.",
      "non_transfer_conditions": ["Ileksa's particular steering, propulsion and windage limitations should not be attributed to vessels with different characteristics or conditions."],
      "supporting_quotes": [
        {
          "page": 11,
          "quote": "because the strong wind was right ahead, and the vessel altered only slowly out of the wind, the action had not started to take effect before the vessels collided."
        },
        {
          "page": 12,
          "quote": "Ileksa’s inherent poor manoeuvring characteristics, especially in the prevailing weather conditions, should have encouraged earlier action"
        }
      ]
    },
    {
      "pages": [8, 14],
      "encounter_types": ["unknown"],
      "roles": ["uncertain"],
      "encounter_phases": ["risk_developing", "action_required"],
      "warning_signs": ["VHF warning lacks the intended vessel's name or call sign", "No response to a warning call"],
      "causal_mechanisms": ["poor_team_coordination", "other"],
      "investigator_finding": "Ileksa's clear VHF transmissions omitted available identifying information and probably failed to attract the distracted OOW's attention.",
      "transferable_lesson": "When using VHF to attract a particular vessel's attention, identify the intended vessel clearly and do not assume that a clear transmission has been recognized or heard.",
      "non_transfer_conditions": ["Clear identification cannot guarantee attention or a response, and this finding does not endorse negotiating avoidance by VHF."],
      "supporting_quotes": [
        {
          "page": 8,
          "quote": "the call did not include the ship’s name, despite this being available to the officers on board Ileksa, from the AIS."
        },
        {
          "page": 8,
          "quote": "Probably because of this, the call did not attract the attention of the OOW on Cepheus J"
        },
        {
          "page": 14,
          "quote": "The sounds recorded by the VDR, on Cepheus J’s bridge, show that these transmissions were clear."
        }
      ]
    },
    {
      "pages": [14],
      "encounter_types": ["unknown"],
      "roles": ["uncertain"],
      "encounter_phases": ["risk_developing", "action_required"],
      "warning_signs": ["Proposal to negotiate avoiding action over VHF"],
      "causal_mechanisms": ["role_confusion", "other"],
      "investigator_finding": "The investigation warned that using VHF to negotiate avoiding action at sea can cause confusion and should be avoided.",
      "transferable_lesson": "Base collision avoidance on the applicable collision regulations rather than a proposed VHF-negotiated arrangement.",
      "non_transfer_conditions": ["The warning concerns negotiating avoiding action, not all use of VHF to identify or alert a vessel."],
      "supporting_quotes": [
        {
          "page": 14,
          "quote": "the use of VHF as a means of negotiating avoiding action at sea can lead to confusion and should be avoided."
        }
      ]
    },
    {
      "pages": [14, 15],
      "encounter_types": ["unknown"],
      "roles": ["uncertain"],
      "encounter_phases": ["action_required", "emergency"],
      "warning_signs": ["Approaching vessel apparently unaware", "VHF attempts unsuccessful", "No other attention-attracting signal attempted"],
      "causal_mechanisms": ["ineffective_action", "other"],
      "investigator_finding": "Ileksa attempted no attention-attracting signals beyond VHF, although signals permitted by the COLREGS might have attracted Cepheus J's attention in time.",
      "transferable_lesson": "Consider appropriate permitted attention-attracting signals when another vessel appears unaware, rather than relying exclusively on unanswered VHF calls.",
      "non_transfer_conditions": ["The finding does not guarantee that a signal will be noticed or justify delaying necessary avoiding action while waiting for a response."],
      "supporting_quotes": [
        {
          "page": 14,
          "quote": "Apart from the use of VHF, no signals were attempted by Ileksa to attract the attention of Cepheus J."
        },
        {
          "page": 15,
          "quote": "Ileksa could have used signals permitted in the COLREGS which might have attracted Cepheus J’s attention in sufficient time to have allowed action to be taken to avoid collision."
        }
      ]
    },
    {
      "pages": [12],
      "encounter_types": ["overtaking", "multi_contact"],
      "roles": ["uncertain"],
      "encounter_phases": ["monitoring", "risk_developing"],
      "warning_signs": ["Following an IMO recommended route", "Other vessels likely to share the same ground track"],
      "causal_mechanisms": ["poor_monitoring"],
      "investigator_finding": "Both vessels' chosen tracks were reasonable, but using the main recommended route should have prompted heightened vigilance for other traffic, including traffic proceeding in the same direction.",
      "transferable_lesson": "Treat a recommended route as a reason to anticipate concentrated traffic and enhance lookout, not as assurance of a clear track.",
      "non_transfer_conditions": ["The route-specific inference of concentrated traffic does not automatically apply to an isolated track without comparable traffic expectations."],
      "supporting_quotes": [
        {
          "page": 12,
          "quote": "Both ships had picked a track 1 mile to the west of the median line, which was a reasonable choice."
        },
        {
          "page": 12,
          "quote": "should have encouraged heightened vigilance due to the increased likelihood of encountering other traffic heading in the same direction."
        },
        {
          "page": 12,
          "quote": "The fact that the chosen track followed an IMO recommended route, should have indicated to the navigator that there might have been other traffic using it, therefore the lookout should have been enhanced."
        }
      ]
    }
  ]
}

{
  "cards": [
    {
      "pages": [5, 10],
      "encounter_types": ["crossing"],
      "roles": ["uncertain"],
      "encounter_phases": ["monitoring", "risk_developing"],
      "warning_signs": ["Substantial difference between heading and course over ground", "A contact fine on the bow appears to be crossing ahead"],
      "causal_mechanisms": ["inadequate_cpa_assessment"],
      "investigator_finding": "The substantial difference between the yacht's heading and course made good contributed to the accident and could invalidate an apparent safe crossing assessment.",
      "transferable_lesson": "Account for actual motion over ground rather than judging a crossing contact's clearance from own heading alone.",
      "non_transfer_conditions": ["The specific heading-versus-track mechanism does not apply where heading and course over ground are effectively aligned."],
      "supporting_quotes": [
        {
          "page": 5,
          "quote": "However, if the great difference between the heading and the actual course made good over the ground is not taken into consideration, the assumption is incorrect, and the yacht could be on collision course with the ship."
        }
      ]
    },
    {
      "pages": [5, 10],
      "encounter_types": ["unknown"],
      "roles": ["uncertain"],
      "encounter_phases": ["monitoring", "risk_developing"],
      "warning_signs": ["Clearance inferred from visual appearance", "No series of compass bearings", "Bearing constant or changing little"],
      "causal_mechanisms": ["poor_monitoring", "inadequate_cpa_assessment"],
      "investigator_finding": "The watchkeepers did not take a series of compass bearings to establish whether the ship was on a collision course.",
      "transferable_lesson": "Use a series of compass bearings to test an apparent safe passage; constant or nearly constant bearings indicate collision risk.",
      "non_transfer_conditions": ["The specific omission is not analogous where a reliable bearing series is already being used to assess risk."],
      "supporting_quotes": [
        {
          "page": 10,
          "quote": "The two watchkeepers did not take a series of compass bearings to determine if the ship was on a collision course."
        },
        {
          "page": 5,
          "quote": "If the bearings remain constant or do not substantially change, a risk of collision exists."
        }
      ]
    },
    {
      "pages": [5, 10],
      "encounter_types": ["unknown"],
      "roles": ["uncertain"],
      "encounter_phases": ["monitoring", "risk_developing"],
      "warning_signs": ["Night-time visual-only assessment", "Range and relative movement inferred from navigation lights", "No radar available"],
      "causal_mechanisms": ["inadequate_cpa_assessment"],
      "investigator_finding": "Difficulty judging range and relative movement visually at night, together with the absence of radar, contributed to the accident.",
      "transferable_lesson": "Treat night-time visual-only estimates of range and relative movement as limited evidence, rather than sufficient assurance of safe clearance.",
      "non_transfer_conditions": ["The visual-only limitation is not directly analogous where reliable radar tracking supplies range and relative-motion information.", "The report's night-time limitation should not be equated with the greater visual references available by day."],
      "supporting_quotes": [
        {
          "page": 10,
          "quote": "The difficulty of assessing, at night, the range and relative movement of an approaching ship by sight alone."
        },
        {
          "page": 10,
          "quote": "The disadvantage of not having a radar set."
        },
        {
          "page": 5,
          "quote": "Without radar, assessing the range of an approaching vessel can be difficult at night because the points of reference to the observer's eye are limited to the navigation lights"
        }
      ]
    },
    {
      "pages": [6, 10],
      "encounter_types": ["crossing"],
      "roles": ["stand_on"],
      "encounter_phases": ["risk_developing", "action_required", "emergency"],
      "warning_signs": ["Give-way vessel not taking appropriate action", "Collision risk recognised only at very close range"],
      "causal_mechanisms": ["delayed_action"],
      "investigator_finding": "The yacht recognised the collision course too late for effective avoiding action; its eventual action was too late to prevent collision.",
      "transferable_lesson": "Being the stand-on vessel does not remove the need to recognise failed give-way action and act while effective avoidance remains possible.",
      "non_transfer_conditions": ["The stand-on aspect does not transfer where own vessel has a different or unresolved obligation.", "The report does not establish that the watchkeepers deliberately followed a rigid stand-on interpretation."],
      "supporting_quotes": [
        {
          "page": 10,
          "quote": "The watchkeepers on the yacht did not appreciate the ship was on a collision course in sufficient time to take effective avoiding action."
        },
        {
          "page": 6,
          "quote": "Although avoiding action was eventually taken by the yacht, it was far too late to prevent a collision."
        },
        {
          "page": 6,
          "quote": "When from any cause, the vessel required to keep her course and speed finds herself so close that collision cannot be avoided by the action (of the give-way vessel alone, she shall take such action as will best aid to avoid collision."
        }
      ]
    },
    {
      "pages": [5, 10],
      "encounter_types": ["multi_contact"],
      "roles": ["stand_on"],
      "encounter_phases": ["risk_developing", "action_required"],
      "warning_signs": ["A second contact appears to block avoiding action", "Proposed action assessed without its effect on sailing motion"],
      "causal_mechanisms": ["ineffective_action", "other"],
      "investigator_finding": "The watchkeepers rejected an avoiding option because of the ferry, although the investigator found that the yacht's response to wind and tide would have allowed collision avoidance.",
      "transferable_lesson": "When another contact appears to constrain action, assess the manoeuvre's actual effect on own vessel's motion and clearance rather than rejecting it from directional appearance alone.",
      "non_transfer_conditions": ["The specific stopping or coming-into-stays response cannot be assumed for a powered vessel or different wind, tide, sail configuration, or manoeuvring characteristics.", "This finding does not justify any particular alteration in another encounter."],
      "supporting_quotes": [
        {
          "page": 5,
          "quote": "Although the watchkeepers considered altering course to starboard, they decided not to do so because they thought this would bring them too close to the ferry."
        },
        {
          "page": 10,
          "quote": "Despite the closeness of the ferry, the yacht could have altered course to starboard into wind and tide, which would have brought her into stays and thereby avoided the collision with the ship."
        }
      ]
    },
    {
      "pages": [5],
      "encounter_types": ["unknown"],
      "roles": ["uncertain"],
      "encounter_phases": ["risk_developing", "action_required"],
      "warning_signs": ["Uncertainty whether an approaching ship has detected a yacht at night"],
      "causal_mechanisms": ["other"],
      "investigator_finding": "The investigator identified illuminating the sails or directing a powerful light towards the ship as an available means of indicating the yacht's presence.",
      "transferable_lesson": "For a yacht in a comparable night encounter, consider the identified means of drawing attention to its presence; do not treat apparent visibility as confirmation of detection.",
      "non_transfer_conditions": ["Sail illumination is not applicable to vessels without sails.", "The report does not establish that the ship failed to detect the yacht or that illumination would guarantee detection or avoidance."],
      "supporting_quotes": [
        {
          "page": 5,
          "quote": "The two watchkeepers on the yacht could have illuminated their sails with a powerful light or directed the light towards the ship to indicate the yacht's presence to those keeping watch on the ship."
        }
      ]
    },
    {
      "pages": [10],
      "encounter_types": ["crossing"],
      "roles": ["give_way"],
      "encounter_phases": ["action_required"],
      "warning_signs": ["An established give-way obligation without avoiding action"],
      "causal_mechanisms": ["other"],
      "investigator_finding": "The ship failed to take avoiding action despite its give-way obligation.",
      "transferable_lesson": "Where a give-way obligation is established, ensure that avoiding action is taken rather than leaving the encounter unresolved.",
      "non_transfer_conditions": ["The ship's give-way role cannot be transferred to another encounter without establishing the applicable obligations.", "The report does not establish why the ship failed to act."],
      "supporting_quotes": [
        {
          "page": 10,
          "quote": "The ship failed to take avoiding action in compliance with her obligation as a give-way vessel under the International Regulations for Preventing Collisions at Sen."
        }
      ]
    },
    {
      "pages": [10],
      "encounter_types": ["crossing"],
      "roles": ["uncertain"],
      "encounter_phases": ["monitoring", "risk_developing", "action_required"],
      "warning_signs": ["A previously apparent crossing-ahead situation changes at close range"],
      "causal_mechanisms": ["other"],
      "investigator_finding": "The investigator retained, as a possibility rather than an established sequence, that the ship had been crossing ahead and then altered towards the yacht at the last minute.",
      "transferable_lesson": "Keep an apparent crossing-ahead assessment under review for subsequent changes in the other vessel's motion.",
      "non_transfer_conditions": ["This possible sequence must not be treated as proof that the ship altered course.", "It does not establish that a safely crossing vessel in another encounter will turn towards own vessel."],
      "supporting_quotes": [
        {
          "page": 10,
          "quote": "The possibility that the ship was, in fact, crossing ahead and altered course towards Bluebell of Warsash at the last minute, possibly in an attempt to avoid a collision with the yacht."
        }
      ]
    }
  ]
}

{
  "cards": [
    {
      "pages": [5, 7],
      "encounter_types": ["crossing", "multi_contact"],
      "roles": ["give_way"],
      "encounter_phases": ["monitoring", "risk_developing", "action_required"],
      "warning_signs": [
        "Collision risk assessed solely from visual relative movement",
        "Radar targets not acquired or plotted",
        "Available bearing-change and CPA information not used"
      ],
      "causal_mechanisms": ["inadequate_cpa_assessment", "poor_monitoring"],
      "investigator_finding": "Philipp's chief officer relied on visual relative movement rather than fully using available navigation information, producing an inaccurate collision-risk assessment.",
      "transferable_lesson": "Use available radar plotting and compass-bearing observations to assess collision risk rather than relying solely on an impression of relative movement.",
      "non_transfer_conditions": [
        "The specific failure to use ARPA does not transfer where ARPA is unavailable; the broader need to use available assessment methods remains.",
        "The report does not establish a numerical CPA threshold for other encounters."
      ],
      "supporting_quotes": [
        {
          "page": 5,
          "quote": "he did not acquire any of the radar targets using ARPA."
        },
        {
          "page": 5,
          "quote": "vessels to use all available means to determine if a risk of collision exists, including radar plotting and compass bearing observations;"
        },
        {
          "page": 7,
          "quote": "Instead, he relied solely on his visual assessment of the relative movement of other vessels. This resulted in him making an inaccurate assessment of the risk of collision with Lynn Marie."
        }
      ]
    },
    {
      "pages": [5],
      "encounter_types": ["multi_contact"],
      "roles": ["uncertain"],
      "encounter_phases": ["monitoring", "risk_developing", "action_required"],
      "warning_signs": [
        "Successive responses to immediate contacts without an overall traffic assessment",
        "Concern about nearby vessels driving action without assessing its consequences for other contacts"
      ],
      "causal_mechanisms": ["poor_monitoring", "inadequate_cpa_assessment"],
      "investigator_finding": "Reduced situational awareness left the chief officer dealing with immediate shipping problems rather than maintaining an overview of traffic and the consequences of his course alterations.",
      "transferable_lesson": "In multi-contact traffic, assess proposed avoiding action against the overall traffic picture, not just the contact currently attracting attention.",
      "non_transfer_conditions": [
        "The multi-contact aspect does not transfer to an isolated encounter with no other relevant traffic."
      ],
      "supporting_quotes": [
        {
          "page": 5,
          "quote": "he was only able to deal with immediate shipping problems, rather than maintain an overview of the traffic situation and the likely consequences of his course alterations."
        }
      ]
    },
    {
      "pages": [4, 5, 7],
      "encounter_types": ["crossing", "multi_contact"],
      "roles": ["give_way"],
      "encounter_phases": ["risk_developing", "action_required"],
      "warning_signs": [
        "Repeated small course alterations made without accurate CPA assessment",
        "Avoiding action shifts passing geometry towards another vessel",
        "A faster vessel's successive alterations create pursuit of a slower contact"
      ],
      "causal_mechanisms": ["repeated_course_changes", "ineffective_action", "inadequate_cpa_assessment"],
      "investigator_finding": "The chief officer's incremental alterations increased collision risk with both fishing vessels and ultimately led Philipp into a curve of pursuit towards Lynn Marie.",
      "transferable_lesson": "Do not assume successive small alterations are making an encounter safer; assess their effect on CPA and ensure avoiding action is readily apparent and produces a safe passing distance.",
      "non_transfer_conditions": [
        "This finding does not establish that every incremental alteration is unsafe.",
        "The pursuit mechanism is not directly analogous where relative motion and manoeuvring do not produce pursuit.",
        "The accident's particular alteration direction is not a general manoeuvring prescription."
      ],
      "supporting_quotes": [
        {
          "page": 5,
          "quote": "he opted to alter course to port in increments to avoid the two fishing vessels ahead. In doing so, the chief officer’s actions increased the risk of collision with both of the fishing vessels."
        },
        {
          "page": 5,
          "quote": "that any alteration of course be readily apparent and result in passing at a safe distance;"
        },
        {
          "page": 7,
          "quote": "The action taken by Philipp’s chief officer to avoid Lynn Marie did not comply with the requirements of the COLREGS, and led to the container ship following a curve of pursuit towards the fishing vessel."
        }
      ]
    },
    {
      "pages": [5, 6, 7],
      "encounter_types": ["crossing"],
      "roles": ["uncertain"],
      "encounter_phases": ["monitoring", "risk_developing", "action_required"],
      "warning_signs": [
        "An initially safe passing assessment is treated as settled",
